use vstd::prelude::*;

verus! {
    /// Function to extract the imaginary parts from an array of complex numbers.
    fn imag(val: Vec<(f64, f64)>) -> Vec<f64>
        requires
            val.len() < 0x1_0000_0000, // Ensure the length of the input vector is within bounds
        ensures
            result.len() == val.len(), // Output length matches input length
            forall|i: nat| 0 <= i < val.len() ==> result[i] == val[i].1, // Output matches imaginary parts
            forall|i: nat| 0 <= i < val.len() ==> (val[i].1 == 0.0 ==> result[i] == 0.0), // Handle zero imaginary parts
            forall|i: nat| 0 <= i < val.len() ==> (val[i] != (0.0, 0.0) ==> result[i] == val[i].1), // Non-zero complex numbers
    {
        let mut result: Vec<f64> = Vec::new();
        let len = val.len();
        let mut idx: usize = 0;

        while idx < len
            invariant
                idx <= len, // Ensure idx does not exceed the length of the input
                result.len() == idx, // The length of the result matches the current index
                forall|j: nat| 0 <= j < idx ==> result[j] == val[j].1, // The result matches the imaginary parts processed so far
            decreases len - idx,
        {
            // Push the imaginary part of the current complex number to the result
            result.push(val[idx].1);
            idx = idx + 1;
        }

        result // Return the result vector containing the imaginary parts
    }
}

